-- Colisoes do artefato ce-main-migration-source-collision-report.
-- Snapshot anterior ao Wave 10: 146 caminhos, 0 aprovacoes. Nao escolhe vencedor.
-- Nao e a lista de 92 do Wave 10; essa lista nao veio itemizada.
create table if not exists canonical_conflict (
  path text primary key,
  domain text not null,
  priority text not null,
  proposed_wo text not null,
  disposition text not null,
  decision text not null default 'NOT_APPROVED' check (decision = 'NOT_APPROVED'),
  kernel_admission text not null default 'NOT_VERIFIED' check (kernel_admission = 'NOT_VERIFIED'),
  revisado boolean not null default false check (revisado = false),
  vencedor text,
  fonte text not null,
  check (vencedor is null)
);
create table if not exists canonical_conflict_source (
  path text not null references canonical_conflict(path),
  branch text not null,
  blob text not null,
  status text not null,
  primary key (path, branch, blob)
);
